package com.aistock.prediction.marketrefs;
import org.junit.jupiter.api.*;import org.flywaydb.core.Flyway;import org.springframework.jdbc.datasource.DriverManagerDataSource;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class MarketReferenceOwnerSchemaMysqlTest {
 @Test void allWhitelistedColumnsExistInActualMigratedOwnerSchema(){String url=System.getenv("PREDICTION_TEST_DB_URL"),password=System.getenv("PREDICTION_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_prediction_test?serverTimezone=UTC".equals(url)||password==null||password.isBlank())throw new IllegalStateException("Explicit isolated owner DB required");var ds=new DriverManagerDataSource(url,"root",password);ds.setDriverClassName("com.mysql.cj.jdbc.Driver");Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var result=new MarketReferenceOwnerConfiguration().marketReferenceScanner(ds).scan("11111111-1111-1111-1111-111111111111");assertEquals("COMPLETE",result.state(),result.toString());assertEquals(19,result.groups().size());assertTrue(result.groups().stream().anyMatch(g->"comparison_market_uses".equals(g.category())));assertTrue(result.groups().stream().anyMatch(g->"prediction_market_uses".equals(g.category())));assertTrue(result.groups().stream().anyMatch(g->"analysis_market_uses".equals(g.category())));assertTrue(result.groups().stream().allMatch(g->g.rows()!=null));}
}
